import java.io.*;import java.util.*;import com.jpexs.decompiler.flash.SWF;import com.jpexs.decompiler.flash.tags.Tag;import com.jpexs.decompiler.flash.abc.avm2.*;import com.jpexs.decompiler.flash.abc.avm2.instructions.*;
class WeddingRoomsPatch{
 static AVM2Instruction i(int op,int...args){return new AVM2Instruction(0,op,args);}
 public static void main(String[]args)throws Exception{SWF s=new SWF(new FileInputStream(args[0]),true);int count=0;for(var pack:s.getAS3Packs())if(pack.getClassPath().toString().equals("marry.room.MarryRoomListFrame")){var a=pack.abc;var init=a.findBodyByClassAndName("MarryRoomListFrame","initItem");var c=init.getCode();int at=-1;for(int n=0;n<c.code.size()-1;n++){var x=c.code.get(n);if(x.definition.instructionName.equals("constructprop")&&a.constants.getString(a.constants.getMultiname(x.operands[0]).name_index).equals("MarryRoomItem")){int next=n+1;if(c.code.get(next).definition.instructionName.equals("coerce"))next++;if(c.code.get(next).definition.instructionName.equals("setlocal1"))at=next+1;}}if(at<0){for(var x:c.code)System.out.println(x.definition.instructionName+" "+Arrays.toString(x.operands));throw new IllegalStateException("Missing native room creation");}int info=a.constants.getPublicQnameId("info",true);init.insertAll(at,List.of(i(0xd1),i(0x20),i(0x61,info)));init.max_stack=Math.max(init.max_stack,3);init.setModified();count++;
 var refresh=a.findBodyByClassAndName("MarryRoomListFrame","refreshView");int items=0,index=0;for(var x:refresh.getCode().code)if(Set.of("getproperty","getlex").contains(x.definition.instructionName)){var m=a.constants.getMultiname(x.operands[0]);if("_itemList".equals(a.constants.getString(m.name_index)))items=x.operands[0];if(m.kind==0x1b)index=x.operands[0];}if(items==0||index==0)throw new IllegalStateException("Missing native array access");int length=a.constants.getPublicQnameId("length",true);var prefix=List.of(i(0x24,0),i(0x63,3),i(0x09),i(0x62,3),i(0x60,items),i(0x66,length),i(0x18,0),i(0x60,items),i(0x62,3),i(0x66,index),i(0x20),i(0x61,info),i(0xc2,3),i(0x10,0));refresh.insertAll(2,prefix);var all=refresh.getCode();int[] offsets=new int[all.code.size()+1];for(int n=0;n<all.code.size();n++)offsets[n+1]=offsets[n]+all.code.get(n).getBytesLength();all.code.get(2+6).operands[0]=offsets[2+prefix.size()]-offsets[2+7];all.code.get(2+13).operands[0]=offsets[2+2]-offsets[2+14];refresh.setCode(all);refresh.max_regs=Math.max(refresh.max_regs,4);refresh.max_stack=Math.max(refresh.max_stack,5);refresh.setModified();((Tag)a.parentTag).setModified(true);count++;}if(count!=2)throw new IllegalStateException("Expected two room methods");try(var out=new FileOutputStream(args[1])){s.saveTo(out);}System.out.println("Wedding room placeholders and stale cards patched");}
}
